(function () {
  if (typeof window === "undefined" || window.Swiper) {
    return
  }

  function Swiper(selector) {
    this.el = typeof selector === "string" ? document.querySelector(selector) : selector
    this.wrapper = this.el ? this.el.querySelector(".swiper-wrapper") : null
    this.slides = this.wrapper ? Array.from(this.wrapper.children) : []
    return this
  }

  Swiper.prototype.update = function () {}
  Swiper.prototype.slideTo = function () {}
  Swiper.prototype.on = function () {}

  window.Swiper = Swiper
})()
